using System.Security.Claims; using Marina.Application.Commerce; using Marina.Persistence.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Authorize,Route("api/v1/orders")]
public sealed class OrdersController(CheckoutService checkout,MarinaDbContext db):ControllerBase{public sealed record CheckoutRequest(Guid AddressId,string IdempotencyKey,List<CheckoutLine>Items,string?CouponCode);[HttpPost]public async Task<ActionResult>Create(CheckoutRequest r,CancellationToken ct){var order=await checkout.CreateAsync(new CheckoutCommand(UserId(),r.AddressId,r.IdempotencyKey,r.Items,r.CouponCode),ct);return Ok(new{order.Id,order.PublicNumber,order.Status,order.Subtotal,order.Discount,order.Shipping,order.Tax,order.Total,Items=order.Items.Select(i=>new{i.Id,i.VariantId,i.ProductName,i.Sku,i.Color,i.Size,i.UnitPrice,i.Discount,i.Quantity})});}[HttpGet]public async Task<ActionResult>List([FromQuery]int page=1,[FromQuery]int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,50);var q=db.Orders.AsNoTracking().Where(x=>x.UserId==UserId()).OrderByDescending(x=>x.CreatedUtc);var total=await q.CountAsync();return Ok(new{items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.PublicNumber,x.Status,x.Total,x.CreatedUtc,ItemCount=x.Items.Sum(i=>i.Quantity)}).ToListAsync(),page,pageSize,total});}[HttpGet("{id:guid}")]public async Task<ActionResult>Details(Guid id){var order=await db.Orders.AsNoTracking().Where(x=>x.Id==id&&x.UserId==UserId()).Select(x=>new{x.Id,x.PublicNumber,x.Status,x.Subtotal,x.Discount,x.Shipping,x.Tax,x.Total,x.RecipientSnapshot,x.AddressSnapshot,Items=x.Items.Select(i=>new{i.Id,i.VariantId,i.ProductName,i.Sku,i.Color,i.Size,i.UnitPrice,i.Discount,i.Quantity}),Timeline=x.StatusHistory.OrderBy(h=>h.CreatedUtc).Select(h=>new{h.Status,h.CreatedUtc,h.Reason})}).SingleOrDefaultAsync();return order is null?NotFound():Ok(order);}[HttpPost("{id:guid}/cancel")]public async Task<IActionResult>Cancel(Guid id,CancelOrderRequest request){var reason=request.Reason;var order=await db.Orders.Include(x=>x.Items).ThenInclude(x=>x.Variant).ThenInclude(x=>x.Inventory).SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId())??throw new KeyNotFoundException("Order not found.");if(order.Status is not(Marina.Domain.Commerce.OrderStatus.Pending or Marina.Domain.Commerce.OrderStatus.Confirmed))return Conflict(new{message="Order can no longer be cancelled."});foreach(var item in order.Items){var old=item.Variant.Inventory.Quantity;item.Variant.Inventory.Quantity+=item.Quantity;db.StockMovements.Add(new Marina.Domain.Commerce.StockMovement{VariantId=item.VariantId,Type=Marina.Domain.Commerce.StockMovementType.Cancellation,OldQuantity=old,Delta=item.Quantity,NewQuantity=old+item.Quantity,Reason=reason??"Customer cancellation",ReferenceId=order.Id,ActorId=UserId()});}order.Status=Marina.Domain.Commerce.OrderStatus.Cancelled;order.StatusHistory.Add(new Marina.Domain.Commerce.OrderStatusHistory{Status=order.Status,ActorId=UserId(),Reason=reason});await db.SaveChangesAsync();return NoContent();}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
